BEGIN; SET LOCAL search_path = ''; DO $preconditions$ DECLARE target_table regclass := pg_catalog.to_regclass('public.push_subscriptions'); users_table regclass := pg_catalog.to_regclass('public.users'); BEGIN IF target_table IS NULL OR users_table IS NULL OR (SELECT relkind FROM pg_catalog.pg_class WHERE oid = target_table) <> 'r' OR pg_catalog.to_regprocedure('public.claim_push_subscription_endpoint(uuid,text,text,text,text)') IS NOT NULL THEN RAISE EXCEPTION 'F016: push subscription endpoint claim preconditions failed'; END IF; END; $preconditions$; CREATE FUNCTION public.claim_push_subscription_endpoint(p_user_id uuid, p_endpoint text, p_p256dh text, p_auth text, p_user_agent text) RETURNS TABLE (id uuid, endpoint text, p256dh text, auth text, user_agent text, created_at timestamptz) LANGUAGE plpgsql SECURITY DEFINER SET search_path = '' AS $function$ DECLARE v_existing boolean; v_raw_count bigint; BEGIN IF p_user_id IS NULL OR p_endpoint IS NULL OR char_length(p_endpoint) NOT BETWEEN 1 AND 2048 OR p_p256dh IS NULL OR p_auth IS NULL THEN RAISE EXCEPTION USING ERRCODE = '22023', MESSAGE = 'Invalid push subscription claim'; END IF; PERFORM pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended('push-subscription-claim', 0)); PERFORM pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended('push-subscription-user:' || p_user_id::text, 0)); PERFORM pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended('push-subscription-endpoint:' || p_endpoint, 0)); PERFORM 1 FROM public.users WHERE id = p_user_id FOR UPDATE; IF NOT FOUND THEN RAISE EXCEPTION 'Push subscription user does not exist'; END IF; PERFORM 1 FROM public.push_subscriptions WHERE user_id = p_user_id FOR UPDATE; SELECT EXISTS (SELECT 1 FROM public.push_subscriptions WHERE user_id = p_user_id AND endpoint = p_endpoint) INTO v_existing; IF NOT v_existing THEN SELECT count(*) INTO v_raw_count FROM public.push_subscriptions WHERE user_id = p_user_id; IF v_raw_count >= 20 THEN RAISE EXCEPTION USING ERRCODE = 'P0001', MESSAGE = 'Push subscription limit reached'; END IF; END IF; PERFORM 1 FROM public.push_subscriptions WHERE endpoint = p_endpoint FOR UPDATE; DELETE FROM public.push_subscriptions WHERE endpoint = p_endpoint AND user_id <> p_user_id; RETURN QUERY INSERT INTO public.push_subscriptions AS subscription (user_id, endpoint, p256dh, auth, user_agent, created_at) VALUES (p_user_id, p_endpoint, p_p256dh, p_auth, p_user_agent, pg_catalog.clock_timestamp()) ON CONFLICT (user_id, endpoint) DO UPDATE SET p256dh = EXCLUDED.p256dh, auth = EXCLUDED.auth, user_agent = EXCLUDED.user_agent, created_at = EXCLUDED.created_at RETURNING subscription.id, subscription.endpoint, subscription.p256dh, subscription.auth, subscription.user_agent, subscription.created_at; END; $function$; REVOKE ALL ON FUNCTION public.claim_push_subscription_endpoint(uuid, text, text, text, text) FROM PUBLIC, anon, authenticated; GRANT EXECUTE ON FUNCTION public.claim_push_subscription_endpoint(uuid, text, text, text, text) TO service_role; DO $verify$ DECLARE function_oid regprocedure := 'public.claim_push_subscription_endpoint(uuid,text,text,text,text)'::regprocedure; target_table regclass := 'public.push_subscriptions'::regclass; BEGIN IF NOT (SELECT procedure.prosecdef AND procedure.proowner = (SELECT relowner FROM pg_catalog.pg_class WHERE oid = target_table) AND procedure.proconfig = ARRAY['search_path=""']::text[] FROM pg_catalog.pg_proc AS procedure WHERE procedure.oid = function_oid) OR NOT pg_catalog.has_function_privilege('service_role', function_oid, 'EXECUTE') OR pg_catalog.has_function_privilege('anon', function_oid, 'EXECUTE') OR pg_catalog.has_function_privilege('authenticated', function_oid, 'EXECUTE') THEN RAISE EXCEPTION 'F016: push subscription endpoint claim ACL is unsafe'; END IF; END; $verify$; COMMIT;
